    const address=email(lead[key]);
    if(!validEmail(address)) continue;
    const verification=(lead.verifications??[]).find(v=>email(v.email)===address);
    // A personal address is a fallback only after a current, conclusive business result.
    if(!verification) return null;
    try {assertFresh(verification.checked_at,now,maxAgeDays,'VERIFICATION');} catch {return null;}
    if(['pending','unknown'].includes(verification.status))return null;
